#!/bin/bash
set -eu
sudo python3 -B - <<'GBP_SUPPLEMENTAL_READONLY_HASH_PINNED'
import base64,hashlib,json,sys,types,zlib
sys.dont_write_bytecode=True
members={'core': {'sha256': '903081856fbdb042b9af74295cbebd6745b57e019e7039a7fce26c23bddde107', 'body': ''}, 'diagnostics': {'sha256': '05ab2bcdb1a00096b9a8df84b82e642109b5efb0b182300643c5155a80c384ca', 'body': ''}, 'supplemental': {'sha256': 'f9b3a2976e561d4deb7ab8fd46415430b3e369d0ba342808b74b07bd77d03751', 'body': ''}}
loaded={}
try:
 for name,member in members.items():
  blob=zlib.decompress(base64.b64decode(member['body']))
  if hashlib.sha256(blob).hexdigest()!=member['sha256']:raise RuntimeError('TOOL_MEMBER_HASH_DRIFT')
  module=types.ModuleType(name);module.__file__='hash-pinned-gbp-supplemental/'+name+'.py';module.__tool_sha256__=member['sha256']
  sys.modules[name]=module;loaded[name]=module
  exec(compile(blob,module.__file__,'exec'),module.__dict__)
 loaded['core'].server_guard()
 loaded['supplemental'].main()
except BaseException as error:
 code=loaded['core'].safe_code(error) if 'core' in loaded else 'PINNED_READONLY_TOOL_REJECTED'
 print(json.dumps({'stage':'GBP_SUPPLEMENTAL_READONLY_REJECTED','code':code}));sys.exit(1)
GBP_SUPPLEMENTAL_READONLY_HASH_PINNED
